#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be a UPROPERTY: NewObject-created UObjects held only by raw C++
	// pointers are invisible to GC and get collected, leaving a dangling pointer.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker was created with NewObject in AArenaGameMode::BeginPlay but stored in a raw C++ pointer (UArenaScoreTracker* ScoreTracker) that was not a UPROPERTY. Unreal's garbage collector only sees UPROPERTY references, so the tracker was collected; the log's 'Collecting garbage: 412 objects purged' happens shortly before the goal, and the subsequent ScoreTracker->AddPoints() call dereferences the dangling pointer, producing EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff. Fix: declare ScoreTracker as UPROPERTY() TObjectPtr<UArenaScoreTracker> so GC keeps it alive.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was not cooked into the packaged build. Packaging uses bCookAll=False and, besides the Arena map, only always-cooks /Game/Data/Effects; the palette is loaded by string via LoadObject('/Game/Data/Palettes/DA_Primary.DA_Primary'), which creates no hard reference for the cooker to follow. In the editor the loose .uasset exists so it loads, but in the pak it is missing, so Palette is null and the arena falls back to gray. Fix: add +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") in Config/DefaultGame.ini so the palette is cooked and packaged."
}
